var HelpRotini = "The companion CLI for Rotini, the spec-first Go CLI framework: scaffold, validate and generate a CLI from its spec.\n\nDocumentation: https://rotini.dev\n\nUsage:\n  rotini [flags] <command>\n\nCommands:\n  initialize, init    scaffold a cli program\n  import              build a rotini spec from an existing cli\n  generate, gen       generate a cli program\n  validate, val       validate a spec and conf\n  tree                print a spec's command tree\n  explain             describe a spec or conf key\n  fmt                 format a spec and conf\n  mount               mount cli specs as sub-commands of another\n  help                print help\n  version             print version\n  completion          print a shell completion script\n  man                 print or install the man pages\n  diff                compare two versions of a cli's contract\n\nFlags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini init mycli\n  rotini validate .rotini.spec.yaml\n  rotini generate ./path/to/.rotini.spec.json\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniInitialize = "Scaffold a new rotini cli — write the spec + conf, then run the first generate (entrypoint, wired handler stubs, codegen) so it is ready to build.\n\nUsage:\n  rotini initialize [flags] <name>\n\nArguments:\n  <name>    the root command name written to the created spec file (expected binary name)\n\nFlags:\n      --format string      the created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n      --template string    start from a shape other than the plain seed [plugin|daemon|suite]\n                             plugin    a kubectl-style plugin named <host>-<plugin>, with completion through the host\n                             daemon    a long-running serve command that stops cleanly on a signal\n                             suite     two binaries composing one shared command from its own spec\n      --force              replace an existing spec and conf, or seed beside one in another format (never deletes a file)\n  -n, --[no-]dry-run       show what init would write, and change nothing\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini initialize mycli\n  rotini init mycli --format json\n  rotini init mycli --force\n  rotini init mycli --dry-run\n  rotini init kubectl-hello --template plugin\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniImport = "Build a rotini spec, conf and handler stubs from an existing Go command-line program, read from the command tree it builds.\n\nUsage:\n  rotini import <command>\n\nCommands:\n  cobra     import a Cobra program\n  kong      import a Kong program\n  urfave    import a urfave/cli v3 program\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini import cobra ./cmd\n  rotini import kong .\n  rotini import urfave ./cmd/acme\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniImportCobra = "Read the command tree a Cobra program builds in <package> and write a rotini spec and\nconf for it under cmd/<dir>, then generate, seeding handler stubs that match the\nimported spec. Anything that can't be carried across exactly is reported on stderr,\none line per item, and in comments in a YAML spec, with the file and line of each\nhook to port.\n\nThe import runs go test in the package with a test file added through -overlay and\nthe importer added to a temporary copy of go.mod, so the program's files and go.mod\nare left as they are. The package's init functions run, as they do in its tests. The\nroot is found from the package's code: a package-level command variable, or a root\nconstructor such as NewRootCmd(); --root names it otherwise.\n\nUsage:\n  rotini import cobra [flags] <package>\n\nArguments:\n  <package>    the Go package that builds the command tree, such as ./cmd\n\nFlags:\n      --root EXPR                  a Go expression, evaluated in the package, that yields a command of the tree\n      --name string                the CLI's name (default the program's root command name)\n      --strict                     give a command with no argument rule only the arguments its usage line names, not any number more\n      --dir string                 the directory under cmd/ and internal/cmd/ to write to (default the CLI's name)\n      --format string              the created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n      --tags string                build tags for go test, comma separated\n      --timeout duration           how long the import's go test may run (default 2m)\n      --importer-version string    the github.com/go-rotini/import version to run (default v0.2.1), or the path of a local checkout, absolute or starting with .\n      --force                      replace an existing spec and conf, and write into an internal/cmd/<dir> rotini didn't generate or beside an existing cmd/<dir>/main.go, which is kept\n  -n, --[no-]dry-run               show what the import would write, and change nothing\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini import cobra ./cmd\n  rotini import cobra --root 'cmds.New(false)' --name dlv ./pkg/terminal/cmds\n  rotini import cobra ./cmd --dir acme-rotini --strict\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniImportKong = "Read the grammar a Kong program declares in <package> and write a rotini spec and\nconf for it under cmd/<dir>, then generate, seeding handler stubs that match the\nimported spec. Anything that can't be carried across exactly is reported on stderr,\none line per item, and in comments in a YAML spec, with the file and line of each\nhook to port.\n\nThe import runs go test in the package with a test file added through -overlay and\nthe importer added to a temporary copy of go.mod, so the program's files and go.mod\nare left as they are. The package's init functions run, as they do in its tests. The\ngrammar is found from the package's code: a package-level grammar variable such as\nvar CLI struct{...}, or a grammar type such as CLI; --root names it otherwise. The\nvariables the program passes to kong.Vars are given with --var; a variable left out\nis reported, and what was built from it is dropped.\n\nUsage:\n  rotini import kong [flags] <package>\n\nArguments:\n  <package>    the Go package that declares the grammar, such as ./cmd/acme\n\nFlags:\n      --root EXPR                  a Go expression, evaluated in the package, that yields a pointer to the grammar\n      --name string                the CLI's name (default the last element of the package's import path)\n      --var NAME=VALUE             a variable the program passes to kong.Vars, as name=value (repeatable)\n      --dir string                 the directory under cmd/ and internal/cmd/ to write to (default the CLI's name)\n      --format string              the created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n      --tags string                build tags for go test, comma separated\n      --timeout duration           how long the import's go test may run (default 2m)\n      --importer-version string    the github.com/go-rotini/import version to run (default v0.2.1), or the path of a local checkout, absolute or starting with .\n      --force                      replace an existing spec and conf, and write into an internal/cmd/<dir> rotini didn't generate or beside an existing cmd/<dir>/main.go, which is kept\n  -n, --[no-]dry-run               show what the import would write, and change nothing\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini import kong .\n  rotini import kong --var version=1.0.0 --name acme ./cmd/acme\n  rotini import kong --root '&grammar' --dir acme-rotini ./cmd/acme\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniImportUrfave = "Read the command tree a urfave/cli v3 program builds in <package> and write a rotini\nspec and conf for it under cmd/<dir>, then generate, seeding handler stubs that match\nthe imported spec. Anything that can't be carried across exactly is reported on\nstderr, one line per item, and in comments in a YAML spec, with the file and line of\neach hook to port.\n\nThe import runs go test in the package with a test file added through -overlay and\nthe importer added to a temporary copy of go.mod, so the program's files and go.mod\nare left as they are. The package's init functions run, as they do in its tests. The\nroot is found from the package's code: a package-level command variable that no other\ncommand lists, or a root constructor such as newApp(); --root names it otherwise.\n\nUsage:\n  rotini import urfave [flags] <package>\n\nArguments:\n  <package>    the Go package that builds the command tree, such as ./cmd/acme\n\nFlags:\n      --root EXPR                  a Go expression, evaluated in the package, that yields the root command\n      --name string                the CLI's name (default the root command's name, else the last element of the package's import path)\n      --strict                     give a command with no arguments declared only the arguments its usage text names, not any number more\n      --dir string                 the directory under cmd/ and internal/cmd/ to write to (default the CLI's name)\n      --format string              the created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n      --tags string                build tags for go test, comma separated\n      --timeout duration           how long the import's go test may run (default 2m)\n      --importer-version string    the github.com/go-rotini/import version to run (default v0.2.1), or the path of a local checkout, absolute or starting with .\n      --force                      replace an existing spec and conf, and write into an internal/cmd/<dir> rotini didn't generate or beside an existing cmd/<dir>/main.go, which is kept\n  -n, --[no-]dry-run               show what the import would write, and change nothing\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini import urfave ./cmd/acme\n  rotini import urfave --root 'buildApp(nil)' --name tasks ./cmd/tasks\n  rotini import urfave ./cmd/acme --dir acme-rotini --strict\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniGenerate = "Generate a cli program from a rotini spec file and its conf.\n\nUsage:\n  rotini generate [flags] [spec_file_path]\n\nArguments:\n  [spec_file_path]    path to the spec file (default the .rotini.spec.* in the working directory)\n\nFlags:\n  -c, --config string    path to the rotini conf file (default the .rotini.conf.* beside the spec)\n  -w, --watch            watch the spec, conf and the files they use for changes and re-generate\n  -n, --[no-]dry-run     show what would be written, created or removed, and change nothing; exits 2 when something would change\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini generate\n  rotini generate ./path/to/.rotini.spec.json --watch\n  rotini generate --dry-run\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniValidate = "Validate a rotini spec file and its conf for correctness.\n\nUsage:\n  rotini validate [flags] [spec_file_path]\n\nArguments:\n  [spec_file_path]    path to the spec file (default the .rotini.spec.* in the working directory)\n\nFlags:\n  -c, --config string    path to the rotini conf file (default the .rotini.conf.* beside the spec)\n      --fail string      failure reporting — fast (first problem) or collect (all); defaults to validate.fail in the conf, else collect [fast|collect]\n  -w, --watch            watch the spec, conf and the files they use for changes and re-validate\n      --release X.Y.Z    fail for each item whose removed_in is at or below this release; defaults to the variable validate.release_env names\n      --format string    how to report problems — text, or json (one object listing every problem, on stdout) (default text) [text|json]\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nOutput:\n  Every problem validate found. Exits 1 when any is an error, 0 when there are only warnings or none.\n  object\n    problems []object    the problems, errors first, each as it is reported in text (required)\n\nExamples:\n  rotini validate\n  rotini val ./path/to/.rotini.spec.yaml\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniTree = "Print the command tree of a rotini spec, with composed children ($ref) resolved: each\ncommand's name and aliases, indented under its parent, with markers for hidden, deprecated,\npassthrough and composed commands and declared plugins.\n\nA mod:// child is downloaded through the module cache, as generate does, so it needs a\ngo.mod and may use the network. A spec with errors is refused; rotini validate explains them.\n\nEffects: read, idempotent\n\nUsage:\n  rotini tree [spec_file_path]\n\nArguments:\n  [spec_file_path]    path to the spec file (default the .rotini.spec.* in the working directory)\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini tree\n  rotini tree ./cmd/musak/.rotini.spec.yaml\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniExplain = "Print what a spec or conf key means: its description, type, allowed values, default and examples, read from the same schemas as the reference pages. Write the keys from the document's top, separated by dots and without list positions: command.flags.schema.from. A key both documents have, such as version, is shown for each.\n\nEffects: read, idempotent, local only\n\nUsage:\n  rotini explain <key>\n\nArguments:\n  <key>    the key path, such as command.flags.schema.from\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini explain command.flags.role\n  rotini explain generate.features.targets\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniFmt = "Rewrite rotini spec, conf and composed command files in canonical form: keys in\nreading order (a command's name and docs, then its inputs, output and sub-commands;\nan input's name and docs, then its behavior, then its schema); two-space indentation,\nwith lists indented under their key; and runs of blank lines folded into one.\nComments stay with the entries they describe, and every value is kept exactly as\nwritten.\n\nWith no file, it formats the .rotini.spec.* in the working directory and the conf\nbeside it. --check writes nothing and exits 2 when a file isn't formatted, for CI.\nOnly YAML files can be formatted for now.\n\nUsage:\n  rotini fmt [flags] [files...]\n\nArguments:\n  [files...]    the files to format (default the spec in the working directory and its conf)\n\nFlags:\n      --check          write nothing; exit 2 when a file isn't formatted\n      --kind string    what the files are, when their keys and names don't tell [spec|conf|command]\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini fmt\n  rotini fmt cmd/app/.rotini.spec.yaml cmd/app/.rotini.conf.yaml\n  rotini fmt --check\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniMount = "Add a $ref entry to the spec named by --into for each spec given, so each cli runs as a\nsub-command of that one and still builds on its own. New entries go after the last $ref\nentry, or at the end of the commands list, with --group written next to each. Every\nother line of the spec is kept as it was.\n\n--under mounts below a command of the --into spec instead of its root, named by its\npath from the root: \"db\" or \"db migrate\". The path can go through any command written in\nthe spec, including one mounted with $ref, whose new entries are added to that cli's own\nsub-commands.\n\nA spec that is already mounted is left alone, and the --into spec itself is skipped, so\na shell wildcard such as cmd/*/.rotini.spec.yaml can name every cli each time. A command\nname or alias that two entries would share is an error, and nothing is written.\n--prune also removes the entries, in the commands list being mounted into, whose spec\nfile no longer exists. Regenerate the parent afterwards. Only YAML specs can be mounted\ninto for now.\n\nUsage:\n  rotini mount [flags] [specs...]\n\nArguments:\n  [specs...]    the spec files to mount\n\nFlags:\n      --into string      the spec to mount into (required)\n      --under COMMAND    mount below this command of the --into spec instead of its root, such as \"db\" or \"db migrate\"\n      --group string     the help group written next to each new entry\n      --prune            remove the entries whose spec file no longer exists\n  -n, --[no-]dry-run     show what would change, and change nothing; exits 2 when something would change\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini mount cmd/db/.rotini.spec.yaml --into cmd/acme/.rotini.spec.yaml\n  rotini mount cmd/*/.rotini.spec.yaml --into cmd/acme/.rotini.spec.yaml --group tools\n  rotini mount cmd/migrate/.rotini.spec.yaml --into cmd/acme/.rotini.spec.yaml --under db\n  rotini mount --prune --into cmd/acme/.rotini.spec.yaml\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniHelp = "Print help for a specific command.\n\nUsage:\n  rotini help [command...]\n\nArguments:\n  [command...]    name of the command to print help for\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini help\n  rotini help generate\n  rotini help init\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniVersion = "Print the rotini cli version. With --format json, print the version, the Go version that built\nthe binary, and the module path and version from its build info, as one JSON object.\n\nUsage:\n  rotini version [flags]\n\nFlags:\n      --format string    output format (default text) [text|json]\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nOutput:\n  The version and build of the rotini binary.\n  object\n    go_version string        the Go toolchain that built the binary, such as go1.27.1 (required)\n    module_path string       the main module path from the build info\n    module_version string    the main module version from the build info: a release, a pseudo-version (with +dirty when built from a modified checkout), or (devel)\n    version string           what rotini version prints, such as v1.4.0 (required)\n\nExamples:\n  rotini version\n  rotini version --format json\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniCompletion = "Print the completion script for a shell. Load it once per session, or install it so\nevery new shell has it:\n\n  bash        source <(rotini completion bash)\n              or save it to ~/.local/share/bash-completion/completions/rotini\n  zsh         rotini completion zsh > \"${fpath[1]}/_rotini\"\n              then start a new shell (compinit must be enabled)\n  fish        rotini completion fish > ~/.config/fish/completions/rotini.fish\n  powershell  rotini completion powershell | Out-String | Invoke-Expression\n              add that line to $PROFILE to load it in every session\n  nushell     rotini completion nushell | save -f ($nu.user-autoload-dirs | first | path join rotini.nu)\n              Nushell 0.116 or later; create the directory first if it is missing\n\nUsage:\n  rotini completion <shell>\n\nArguments:\n  <shell>    the shell to print the script for [bash|zsh|fish|powershell|nushell]\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini completion bash\n  rotini completion zsh > \"${fpath[1]}/_rotini\"\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniMan = "Print a command's man page as roff, the markup the man program reads, or write every\npage into a directory with --dir. With no command, it prints the page for rotini itself.\n\nThe pages are named after the command path, rotini-generate.1, so a directory written\nwith --dir can be added to MANPATH or copied into a man1 directory.\n\nUsage:\n  rotini man [flags] [command...]\n\nArguments:\n  [command...]    the command whose page to print (default rotini itself)\n\nFlags:\n      --dir string    write every page into this directory instead of printing one\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nExamples:\n  rotini man generate > rotini-generate.1\n  rotini man --dir ~/.local/share/man/man1\n\nUse \"rotini help <command>\" for more information about a command."

var HelpRotiniDiff = "Compare two versions of a cli's contract and report each change for the people and\nscripts using it: breaking, possibly breaking, expected (a removal planned for this\nrelease) or safe. Findings are written to stdout, grouped by severity.\n\n<old> is a contract file, git:<ref> (the conf's generate.contract.file at that\nrevision, read with git show), git:<ref>:<path> (a module-root-relative file at that\nrevision) or mod://<module>@<version>/<path>. <new> takes the same forms and defaults\nto the contract built from the current spec and conf. Because both arguments are\ncontracts, the spec is given with --spec.\n\nThe conf's diff.accept entries acknowledge intended changes, one finding each; an entry\nthat matches no finding fails the run, unless --fail-on is never.\n\nUsage:\n  rotini diff [flags] <old> [new]\n\nArguments:\n  <old>    the earlier contract: a file, git:<ref>[:<path>] or mod://<module>@<version>/<path>\n  [new]    the later contract (default the one built from the current spec and conf)\n\nFlags:\n      --spec string       path to the spec file (default the .rotini.spec.* in the working directory)\n  -c, --config string     path to the rotini conf file (default the .rotini.conf.* beside the spec)\n      --release X.Y.Z     report a removal the old contract planned for this release or earlier as expected; defaults to the variable validate.release_env names\n      --fail-on string    the least severe change that fails the run (default breaking) [breaking|possibly|never]\n      --format string     how to write the findings (default text) [text|json]\n\nGlobal Flags:\n      --version    print version\n  -h, --help       print help\n\nOutput:\n  Every change between the contracts, the acknowledgements that matched none, and the counts.\n  object\n    findings []object             The changes, most severe first, then by where. (required)\n    summary object                The changes by severity; an accepted change counts only as accepted. (required)\n    unmatched_accepts []object    The diff.accept entries that matched no change. (required)\n\nExamples:\n  rotini diff git:v1.2.0\n  rotini diff git:v1.2.0 --release 2.0.0\n  rotini diff old/cli-contract.json cli-contract.json --format json\n\nUse \"rotini help <command>\" for more information about a command."

// Help returns the generated help text for the command identified by path
// (command names or aliases; no arguments for the root command). It returns an
// error when path does not match a known command.
func Help(path ...string) (string, error) {
	switch rotiniCanonicalPath(path) {
	case "":
		return HelpRotini, nil
	case "initialize":
		return HelpRotiniInitialize, nil
	case "import":
		return HelpRotiniImport, nil
	case "import cobra":
		return HelpRotiniImportCobra, nil
	case "import kong":
		return HelpRotiniImportKong, nil
	case "import urfave":
		return HelpRotiniImportUrfave, nil
	case "generate":
		return HelpRotiniGenerate, nil
	case "validate":
		return HelpRotiniValidate, nil
	case "tree":
		return HelpRotiniTree, nil
	case "explain":
		return HelpRotiniExplain, nil
	case "fmt":
		return HelpRotiniFmt, nil
	case "mount":
		return HelpRotiniMount, nil
	case "help":
		return HelpRotiniHelp, nil
	case "version":
		return HelpRotiniVersion, nil
	case "completion":
		return HelpRotiniCompletion, nil
	case "man":
		return HelpRotiniMan, nil
	case "diff":
		return HelpRotiniDiff, nil
	default:
		return "", fmt.Errorf("no help for command %q", strings.Join(path, " "))
	}
}

var ManRotini = ".TH \"ROTINI\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini \\- scaffold, validate and generate rotini CLIs\n.SH SYNOPSIS\n\\fBrotini\\fR [flags] <command>\n.SH DESCRIPTION\nThe companion CLI for Rotini, the spec\\-first Go CLI framework: scaffold,\nvalidate and generate a CLI from its spec.\n.PP\nDocumentation: https://rotini.dev\n.SH \"COMMANDS\"\n.TP\n\\fBinitialize\\fR, \\fBinit\\fR\nscaffold a cli program\n.TP\n\\fBimport\\fR\nbuild a rotini spec from an existing cli\n.TP\n\\fBgenerate\\fR, \\fBgen\\fR\ngenerate a cli program\n.TP\n\\fBvalidate\\fR, \\fBval\\fR\nvalidate a spec and conf\n.TP\n\\fBtree\\fR\nprint a spec\\(aqs command tree\n.TP\n\\fBexplain\\fR\ndescribe a spec or conf key\n.TP\n\\fBfmt\\fR\nformat a spec and conf\n.TP\n\\fBmount\\fR\nmount cli specs as sub\\-commands of another\n.TP\n\\fBhelp\\fR\nprint help\n.TP\n\\fBversion\\fR\nprint version\n.TP\n\\fBcompletion\\fR\nprint a shell completion script\n.TP\n\\fBman\\fR\nprint or install the man pages\n.TP\n\\fBdiff\\fR\ncompare two versions of a cli\\(aqs contract\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH ENVIRONMENT\n.TP\n\\fBROTINI_COMPLETION_MESSAGES\\fR\nset to 0, false or off to hide completion messages\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini init mycli\n.sp\nrotini validate .rotini.spec.yaml\n.sp\nrotini generate ./path/to/.rotini.spec.json\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\-initialize\\fR(1), \\fBrotini\\-import\\fR(1), \\fBrotini\\-generate\\fR(1),\n\\fBrotini\\-validate\\fR(1), \\fBrotini\\-tree\\fR(1), \\fBrotini\\-explain\\fR(1),\n\\fBrotini\\-fmt\\fR(1), \\fBrotini\\-mount\\fR(1), \\fBrotini\\-help\\fR(1),\n\\fBrotini\\-version\\fR(1), \\fBrotini\\-completion\\fR(1), \\fBrotini\\-man\\fR(1),\n\\fBrotini\\-diff\\fR(1)\n"

var ManRotiniInitialize = ".TH \"ROTINI\\-INITIALIZE\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-initialize \\- scaffold a cli program\n.SH SYNOPSIS\n\\fBrotini initialize\\fR [flags] <name>\n.SH DESCRIPTION\nScaffold a new rotini cli \\[u2014] write the spec + conf, then run the first\ngenerate (entrypoint, wired handler stubs, codegen) so it is ready to build.\n.SH ARGUMENTS\n.TP\n\\fI<name>\\fR\nthe root command name written to the created spec file (expected binary name)\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-format\\fR \\fIstring\\fR\nthe created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n.TP\n\\fB\\-\\-template\\fR \\fIstring\\fR\nstart from a shape other than the plain seed [plugin|daemon|suite]\n.RS\n.RS 2\n\\fBplugin\\fR \\- a kubectl\\-style plugin named <host>\\-<plugin>, with completion\nthrough the host\n.br\n\\fBdaemon\\fR \\- a long\\-running serve command that stops cleanly on a signal\n.br\n\\fBsuite\\fR \\- two binaries composing one shared command from its own spec\n.RE\n.RE\n.TP\n\\fB\\-\\-force\\fR\nreplace an existing spec and conf, or seed beside one in another format (never\ndeletes a file)\n.TP\n\\fB\\-n\\fR, \\fB\\-\\-[no\\-]dry\\-run\\fR\nshow what init would write, and change nothing\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini initialize mycli\n.sp\nrotini init mycli \\-\\-format json\n.sp\nrotini init mycli \\-\\-force\n.sp\nrotini init mycli \\-\\-dry\\-run\n.sp\nrotini init kubectl\\-hello \\-\\-template plugin\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniImport = ".TH \"ROTINI\\-IMPORT\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-import \\- build a rotini spec from an existing cli\n.SH SYNOPSIS\n\\fBrotini import\\fR <command>\n.SH DESCRIPTION\nBuild a rotini spec, conf and handler stubs from an existing Go command\\-line\nprogram, read from the command tree it builds.\n.SH \"COMMANDS\"\n.TP\n\\fBcobra\\fR\nimport a Cobra program\n.TP\n\\fBkong\\fR\nimport a Kong program\n.TP\n\\fBurfave\\fR\nimport a urfave/cli v3 program\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini import cobra ./cmd\n.sp\nrotini import kong .\n.sp\nrotini import urfave ./cmd/acme\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1), \\fBrotini\\-import\\-cobra\\fR(1), \\fBrotini\\-import\\-kong\\fR(1),\n\\fBrotini\\-import\\-urfave\\fR(1)\n"

var ManRotiniImportCobra = ".TH \"ROTINI\\-IMPORT\\-COBRA\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-import\\-cobra \\- import a Cobra program\n.SH SYNOPSIS\n\\fBrotini import cobra\\fR [flags] <package>\n.SH DESCRIPTION\nRead the command tree a Cobra program builds in <package> and write a rotini\nspec and\nconf for it under cmd/<dir>, then generate, seeding handler stubs that match the\nimported spec. Anything that can\\(aqt be carried across exactly is reported on\nstderr,\none line per item, and in comments in a YAML spec, with the file and line of\neach\nhook to port.\n.PP\nThe import runs go test in the package with a test file added through \\-overlay\nand\nthe importer added to a temporary copy of go.mod, so the program\\(aqs files and\ngo.mod\nare left as they are. The package\\(aqs init functions run, as they do in its\ntests. The\nroot is found from the package\\(aqs code: a package\\-level command variable, or\na root\nconstructor such as NewRootCmd(); \\-\\-root names it otherwise.\n.SH ARGUMENTS\n.TP\n\\fI<package>\\fR\nthe Go package that builds the command tree, such as ./cmd\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-root\\fR \\fIEXPR\\fR\na Go expression, evaluated in the package, that yields a command of the tree\n.TP\n\\fB\\-\\-name\\fR \\fIstring\\fR\nthe CLI\\(aqs name (default the program\\(aqs root command name)\n.TP\n\\fB\\-\\-strict\\fR\ngive a command with no argument rule only the arguments its usage line names,\nnot any number more\n.TP\n\\fB\\-\\-dir\\fR \\fIstring\\fR\nthe directory under cmd/ and internal/cmd/ to write to (default the CLI\\(aqs\nname)\n.TP\n\\fB\\-\\-format\\fR \\fIstring\\fR\nthe created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n.TP\n\\fB\\-\\-tags\\fR \\fIstring\\fR\nbuild tags for go test, comma separated\n.TP\n\\fB\\-\\-timeout\\fR \\fIduration\\fR\nhow long the import\\(aqs go test may run (default 2m)\n.TP\n\\fB\\-\\-importer\\-version\\fR \\fIstring\\fR\nthe github.com/go\\-rotini/import version to run (default v0.2.1), or the path of\na local checkout, absolute or starting with .\n.TP\n\\fB\\-\\-force\\fR\nreplace an existing spec and conf, and write into an internal/cmd/<dir> rotini\ndidn\\(aqt generate or beside an existing cmd/<dir>/main.go, which is kept\n.TP\n\\fB\\-n\\fR, \\fB\\-\\-[no\\-]dry\\-run\\fR\nshow what the import would write, and change nothing\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini import cobra ./cmd\n.sp\nrotini import cobra \\-\\-root \\(aqcmds.New(false)\\(aq \\-\\-name dlv ./pkg/terminal/cmds\n.sp\nrotini import cobra ./cmd \\-\\-dir acme\\-rotini \\-\\-strict\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\-import\\fR(1)\n"

var ManRotiniImportKong = ".TH \"ROTINI\\-IMPORT\\-KONG\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-import\\-kong \\- import a Kong program\n.SH SYNOPSIS\n\\fBrotini import kong\\fR [flags] <package>\n.SH DESCRIPTION\nRead the grammar a Kong program declares in <package> and write a rotini spec\nand\nconf for it under cmd/<dir>, then generate, seeding handler stubs that match the\nimported spec. Anything that can\\(aqt be carried across exactly is reported on\nstderr,\none line per item, and in comments in a YAML spec, with the file and line of\neach\nhook to port.\n.PP\nThe import runs go test in the package with a test file added through \\-overlay\nand\nthe importer added to a temporary copy of go.mod, so the program\\(aqs files and\ngo.mod\nare left as they are. The package\\(aqs init functions run, as they do in its\ntests. The\ngrammar is found from the package\\(aqs code: a package\\-level grammar variable\nsuch as\nvar CLI struct{...}, or a grammar type such as CLI; \\-\\-root names it otherwise.\nThe\nvariables the program passes to kong.Vars are given with \\-\\-var; a variable\nleft out\nis reported, and what was built from it is dropped.\n.SH ARGUMENTS\n.TP\n\\fI<package>\\fR\nthe Go package that declares the grammar, such as ./cmd/acme\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-root\\fR \\fIEXPR\\fR\na Go expression, evaluated in the package, that yields a pointer to the grammar\n.TP\n\\fB\\-\\-name\\fR \\fIstring\\fR\nthe CLI\\(aqs name (default the last element of the package\\(aqs import path)\n.TP\n\\fB\\-\\-var\\fR \\fINAME=VALUE\\fR\na variable the program passes to kong.Vars, as name=value\n.br\nrepeatable\n.TP\n\\fB\\-\\-dir\\fR \\fIstring\\fR\nthe directory under cmd/ and internal/cmd/ to write to (default the CLI\\(aqs\nname)\n.TP\n\\fB\\-\\-format\\fR \\fIstring\\fR\nthe created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n.TP\n\\fB\\-\\-tags\\fR \\fIstring\\fR\nbuild tags for go test, comma separated\n.TP\n\\fB\\-\\-timeout\\fR \\fIduration\\fR\nhow long the import\\(aqs go test may run (default 2m)\n.TP\n\\fB\\-\\-importer\\-version\\fR \\fIstring\\fR\nthe github.com/go\\-rotini/import version to run (default v0.2.1), or the path of\na local checkout, absolute or starting with .\n.TP\n\\fB\\-\\-force\\fR\nreplace an existing spec and conf, and write into an internal/cmd/<dir> rotini\ndidn\\(aqt generate or beside an existing cmd/<dir>/main.go, which is kept\n.TP\n\\fB\\-n\\fR, \\fB\\-\\-[no\\-]dry\\-run\\fR\nshow what the import would write, and change nothing\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini import kong .\n.sp\nrotini import kong \\-\\-var version=1.0.0 \\-\\-name acme ./cmd/acme\n.sp\nrotini import kong \\-\\-root \\(aq&grammar\\(aq \\-\\-dir acme\\-rotini ./cmd/acme\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\-import\\fR(1)\n"

var ManRotiniImportUrfave = ".TH \"ROTINI\\-IMPORT\\-URFAVE\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-import\\-urfave \\- import a urfave/cli v3 program\n.SH SYNOPSIS\n\\fBrotini import urfave\\fR [flags] <package>\n.SH DESCRIPTION\nRead the command tree a urfave/cli v3 program builds in <package> and write a\nrotini\nspec and conf for it under cmd/<dir>, then generate, seeding handler stubs that\nmatch\nthe imported spec. Anything that can\\(aqt be carried across exactly is reported\non\nstderr, one line per item, and in comments in a YAML spec, with the file and\nline of\neach hook to port.\n.PP\nThe import runs go test in the package with a test file added through \\-overlay\nand\nthe importer added to a temporary copy of go.mod, so the program\\(aqs files and\ngo.mod\nare left as they are. The package\\(aqs init functions run, as they do in its\ntests. The\nroot is found from the package\\(aqs code: a package\\-level command variable that\nno other\ncommand lists, or a root constructor such as newApp(); \\-\\-root names it\notherwise.\n.SH ARGUMENTS\n.TP\n\\fI<package>\\fR\nthe Go package that builds the command tree, such as ./cmd/acme\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-root\\fR \\fIEXPR\\fR\na Go expression, evaluated in the package, that yields the root command\n.TP\n\\fB\\-\\-name\\fR \\fIstring\\fR\nthe CLI\\(aqs name (default the root command\\(aqs name, else the last element of\nthe package\\(aqs import path)\n.TP\n\\fB\\-\\-strict\\fR\ngive a command with no arguments declared only the arguments its usage text\nnames, not any number more\n.TP\n\\fB\\-\\-dir\\fR \\fIstring\\fR\nthe directory under cmd/ and internal/cmd/ to write to (default the CLI\\(aqs\nname)\n.TP\n\\fB\\-\\-format\\fR \\fIstring\\fR\nthe created rotini spec file format (default yaml) [yaml|yml|json|jsonc|toml]\n.TP\n\\fB\\-\\-tags\\fR \\fIstring\\fR\nbuild tags for go test, comma separated\n.TP\n\\fB\\-\\-timeout\\fR \\fIduration\\fR\nhow long the import\\(aqs go test may run (default 2m)\n.TP\n\\fB\\-\\-importer\\-version\\fR \\fIstring\\fR\nthe github.com/go\\-rotini/import version to run (default v0.2.1), or the path of\na local checkout, absolute or starting with .\n.TP\n\\fB\\-\\-force\\fR\nreplace an existing spec and conf, and write into an internal/cmd/<dir> rotini\ndidn\\(aqt generate or beside an existing cmd/<dir>/main.go, which is kept\n.TP\n\\fB\\-n\\fR, \\fB\\-\\-[no\\-]dry\\-run\\fR\nshow what the import would write, and change nothing\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini import urfave ./cmd/acme\n.sp\nrotini import urfave \\-\\-root \\(aqbuildApp(nil)\\(aq \\-\\-name tasks ./cmd/tasks\n.sp\nrotini import urfave ./cmd/acme \\-\\-dir acme\\-rotini \\-\\-strict\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\-import\\fR(1)\n"

var ManRotiniGenerate = ".TH \"ROTINI\\-GENERATE\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-generate \\- generate a cli program\n.SH SYNOPSIS\n\\fBrotini generate\\fR [flags] [spec_file_path]\n.SH DESCRIPTION\nGenerate a cli program from a rotini spec file and its conf.\n.SH ARGUMENTS\n.TP\n\\fI[spec_file_path]\\fR\npath to the spec file (default the .rotini.spec.* in the working directory)\n.SH \"OPTIONS\"\n.TP\n\\fB\\-c\\fR, \\fB\\-\\-config\\fR \\fIstring\\fR\npath to the rotini conf file (default the .rotini.conf.* beside the spec)\n.TP\n\\fB\\-w\\fR, \\fB\\-\\-watch\\fR\nwatch the spec, conf and the files they use for changes and re\\-generate\n.TP\n\\fB\\-n\\fR, \\fB\\-\\-[no\\-]dry\\-run\\fR\nshow what would be written, created or removed, and change nothing; exits 2 when\nsomething would change\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini generate\n.sp\nrotini generate ./path/to/.rotini.spec.json \\-\\-watch\n.sp\nrotini generate \\-\\-dry\\-run\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniValidate = ".TH \"ROTINI\\-VALIDATE\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-validate \\- validate a spec and conf\n.SH SYNOPSIS\n\\fBrotini validate\\fR [flags] [spec_file_path]\n.SH DESCRIPTION\nValidate a rotini spec file and its conf for correctness.\n.SH ARGUMENTS\n.TP\n\\fI[spec_file_path]\\fR\npath to the spec file (default the .rotini.spec.* in the working directory)\n.SH \"OPTIONS\"\n.TP\n\\fB\\-c\\fR, \\fB\\-\\-config\\fR \\fIstring\\fR\npath to the rotini conf file (default the .rotini.conf.* beside the spec)\n.TP\n\\fB\\-\\-fail\\fR \\fIstring\\fR\nfailure reporting \\[u2014] fast (first problem) or collect (all); defaults to\nvalidate.fail in the conf, else collect [fast|collect]\n.TP\n\\fB\\-w\\fR, \\fB\\-\\-watch\\fR\nwatch the spec, conf and the files they use for changes and re\\-validate\n.TP\n\\fB\\-\\-release\\fR \\fIX.Y.Z\\fR\nfail for each item whose removed_in is at or below this release; defaults to the\nvariable validate.release_env names\n.TP\n\\fB\\-\\-format\\fR \\fIstring\\fR\nhow to report problems \\[u2014] text, or json (one object listing every problem,\non stdout) (default text) [text|json]\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH OUTPUT\nEvery problem validate found. Exits 1 when any is an error, 0 when there are\nonly warnings or none.\n.PP\nWrites \\fBobject\\fR to standard output.\n.TP\n\\fBproblems\\fR \\fI[]object\\fR\nthe problems, errors first, each as it is reported in text (required)\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini validate\n.sp\nrotini val ./path/to/.rotini.spec.yaml\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniTree = ".TH \"ROTINI\\-TREE\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-tree \\- print a spec\\(aqs command tree\n.SH SYNOPSIS\n\\fBrotini tree\\fR [spec_file_path]\n.SH DESCRIPTION\nPrint the command tree of a rotini spec, with composed children ($ref) resolved:\neach\ncommand\\(aqs name and aliases, indented under its parent, with markers for\nhidden, deprecated,\npassthrough and composed commands and declared plugins.\n.PP\nA mod:// child is downloaded through the module cache, as generate does, so it\nneeds a\ngo.mod and may use the network. A spec with errors is refused; rotini validate\nexplains them.\n.PP\nEffects: read, idempotent\n.SH ARGUMENTS\n.TP\n\\fI[spec_file_path]\\fR\npath to the spec file (default the .rotini.spec.* in the working directory)\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini tree\n.sp\nrotini tree ./cmd/musak/.rotini.spec.yaml\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniExplain = ".TH \"ROTINI\\-EXPLAIN\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-explain \\- describe a spec or conf key\n.SH SYNOPSIS\n\\fBrotini explain\\fR <key>\n.SH DESCRIPTION\nPrint what a spec or conf key means: its description, type, allowed values,\ndefault and examples, read from the same schemas as the reference pages. Write\nthe keys from the document\\(aqs top, separated by dots and without list\npositions: command.flags.schema.from. A key both documents have, such as\nversion, is shown for each.\n.PP\nEffects: read, idempotent, local only\n.SH ARGUMENTS\n.TP\n\\fI<key>\\fR\nthe key path, such as command.flags.schema.from\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini explain command.flags.role\n.sp\nrotini explain generate.features.targets\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniFmt = ".TH \"ROTINI\\-FMT\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-fmt \\- format a spec and conf\n.SH SYNOPSIS\n\\fBrotini fmt\\fR [flags] [files...]\n.SH DESCRIPTION\nRewrite rotini spec, conf and composed command files in canonical form: keys in\nreading order (a command\\(aqs name and docs, then its inputs, output and\nsub\\-commands;\nan input\\(aqs name and docs, then its behavior, then its schema); two\\-space\nindentation,\nwith lists indented under their key; and runs of blank lines folded into one.\nComments stay with the entries they describe, and every value is kept exactly as\nwritten.\n.PP\nWith no file, it formats the .rotini.spec.* in the working directory and the\nconf\nbeside it. \\-\\-check writes nothing and exits 2 when a file isn\\(aqt formatted,\nfor CI.\nOnly YAML files can be formatted for now.\n.SH ARGUMENTS\n.TP\n\\fI[files...]\\fR\nthe files to format (default the spec in the working directory and its conf)\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-check\\fR\nwrite nothing; exit 2 when a file isn\\(aqt formatted\n.TP\n\\fB\\-\\-kind\\fR \\fIstring\\fR\nwhat the files are, when their keys and names don\\(aqt tell [spec|conf|command]\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini fmt\n.sp\nrotini fmt cmd/app/.rotini.spec.yaml cmd/app/.rotini.conf.yaml\n.sp\nrotini fmt \\-\\-check\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniMount = ".TH \"ROTINI\\-MOUNT\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-mount \\- mount cli specs as sub\\-commands of another\n.SH SYNOPSIS\n\\fBrotini mount\\fR [flags] [specs...]\n.SH DESCRIPTION\nAdd a $ref entry to the spec named by \\-\\-into for each spec given, so each cli\nruns as a\nsub\\-command of that one and still builds on its own. New entries go after the\nlast $ref\nentry, or at the end of the commands list, with \\-\\-group written next to each.\nEvery\nother line of the spec is kept as it was.\n.PP\n\\-\\-under mounts below a command of the \\-\\-into spec instead of its root, named\nby its\npath from the root: \"db\" or \"db migrate\". The path can go through any command\nwritten in\nthe spec, including one mounted with $ref, whose new entries are added to that\ncli\\(aqs own\nsub\\-commands.\n.PP\nA spec that is already mounted is left alone, and the \\-\\-into spec itself is\nskipped, so\na shell wildcard such as cmd/*/.rotini.spec.yaml can name every cli each time. A\ncommand\nname or alias that two entries would share is an error, and nothing is written.\n\\-\\-prune also removes the entries, in the commands list being mounted into,\nwhose spec\nfile no longer exists. Regenerate the parent afterwards. Only YAML specs can be\nmounted\ninto for now.\n.SH ARGUMENTS\n.TP\n\\fI[specs...]\\fR\nthe spec files to mount\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-into\\fR \\fIstring\\fR\nthe spec to mount into (required)\n.TP\n\\fB\\-\\-under\\fR \\fICOMMAND\\fR\nmount below this command of the \\-\\-into spec instead of its root, such as \"db\"\nor \"db migrate\"\n.TP\n\\fB\\-\\-group\\fR \\fIstring\\fR\nthe help group written next to each new entry\n.TP\n\\fB\\-\\-prune\\fR\nremove the entries whose spec file no longer exists\n.TP\n\\fB\\-n\\fR, \\fB\\-\\-[no\\-]dry\\-run\\fR\nshow what would change, and change nothing; exits 2 when something would change\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini mount cmd/db/.rotini.spec.yaml \\-\\-into cmd/acme/.rotini.spec.yaml\n.sp\nrotini mount cmd/*/.rotini.spec.yaml \\-\\-into cmd/acme/.rotini.spec.yaml \\-\\-group tools\n.sp\nrotini mount cmd/migrate/.rotini.spec.yaml \\-\\-into cmd/acme/.rotini.spec.yaml \\-\\-under db\n.sp\nrotini mount \\-\\-prune \\-\\-into cmd/acme/.rotini.spec.yaml\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniHelp = ".TH \"ROTINI\\-HELP\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-help \\- print help\n.SH SYNOPSIS\n\\fBrotini help\\fR [command...]\n.SH DESCRIPTION\nPrint help for a specific command.\n.SH ARGUMENTS\n.TP\n\\fI[command...]\\fR\nname of the command to print help for\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini help\n.sp\nrotini help generate\n.sp\nrotini help init\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniVersion = ".TH \"ROTINI\\-VERSION\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-version \\- print version\n.SH SYNOPSIS\n\\fBrotini version\\fR [flags]\n.SH DESCRIPTION\nPrint the rotini cli version. With \\-\\-format json, print the version, the Go\nversion that built\nthe binary, and the module path and version from its build info, as one JSON\nobject.\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-format\\fR \\fIstring\\fR\noutput format (default text) [text|json]\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH OUTPUT\nThe version and build of the rotini binary.\n.PP\nWrites \\fBobject\\fR to standard output.\n.TP\n\\fBgo_version\\fR \\fIstring\\fR\nthe Go toolchain that built the binary, such as go1.27.1 (required)\n.TP\n\\fBmodule_path\\fR \\fIstring\\fR\nthe main module path from the build info\n.TP\n\\fBmodule_version\\fR \\fIstring\\fR\nthe main module version from the build info: a release, a pseudo\\-version (with\n+dirty when built from a modified checkout), or (devel)\n.TP\n\\fBversion\\fR \\fIstring\\fR\nwhat rotini version prints, such as v1.4.0 (required)\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini version\n.sp\nrotini version \\-\\-format json\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniCompletion = ".TH \"ROTINI\\-COMPLETION\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-completion \\- print a shell completion script\n.SH SYNOPSIS\n\\fBrotini completion\\fR <shell>\n.SH DESCRIPTION\nPrint the completion script for a shell. Load it once per session, or install it\nso\nevery new shell has it:\n.PP\n.nf\n  bash        source <(rotini completion bash)\n              or save it to ~/.local/share/bash\\-completion/completions/rotini\n  zsh         rotini completion zsh > \"${fpath[1]}/_rotini\"\n              then start a new shell (compinit must be enabled)\n  fish        rotini completion fish > ~/.config/fish/completions/rotini.fish\n  powershell  rotini completion powershell | Out\\-String | Invoke\\-Expression\n              add that line to $PROFILE to load it in every session\n  nushell     rotini completion nushell | save \\-f ($nu.user\\-autoload\\-dirs | first | path join rotini.nu)\n              Nushell 0.116 or later; create the directory first if it is missing\n.fi\n.SH ARGUMENTS\n.TP\n\\fI<shell>\\fR\nthe shell to print the script for [bash|zsh|fish|powershell|nushell]\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini completion bash\n.sp\nrotini completion zsh > \"${fpath[1]}/_rotini\"\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniMan = ".TH \"ROTINI\\-MAN\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-man \\- print or install the man pages\n.SH SYNOPSIS\n\\fBrotini man\\fR [flags] [command...]\n.SH DESCRIPTION\nPrint a command\\(aqs man page as roff, the markup the man program reads, or\nwrite every\npage into a directory with \\-\\-dir. With no command, it prints the page for\nrotini itself.\n.PP\nThe pages are named after the command path, rotini\\-generate.1, so a directory\nwritten\nwith \\-\\-dir can be added to MANPATH or copied into a man1 directory.\n.SH ARGUMENTS\n.TP\n\\fI[command...]\\fR\nthe command whose page to print (default rotini itself)\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-dir\\fR \\fIstring\\fR\nwrite every page into this directory instead of printing one\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini man generate > rotini\\-generate.1\n.sp\nrotini man \\-\\-dir ~/.local/share/man/man1\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

var ManRotiniDiff = ".TH \"ROTINI\\-DIFF\" 1 \"\" \"rotini\" \"User Commands\"\n.SH NAME\nrotini\\-diff \\- compare two versions of a cli\\(aqs contract\n.SH SYNOPSIS\n\\fBrotini diff\\fR [flags] <old> [new]\n.SH DESCRIPTION\nCompare two versions of a cli\\(aqs contract and report each change for the\npeople and\nscripts using it: breaking, possibly breaking, expected (a removal planned for\nthis\nrelease) or safe. Findings are written to stdout, grouped by severity.\n.PP\n<old> is a contract file, git:<ref> (the conf\\(aqs generate.contract.file at\nthat\nrevision, read with git show), git:<ref>:<path> (a module\\-root\\-relative file\nat that\nrevision) or mod://<module>@<version>/<path>. <new> takes the same forms and\ndefaults\nto the contract built from the current spec and conf. Because both arguments are\ncontracts, the spec is given with \\-\\-spec.\n.PP\nThe conf\\(aqs diff.accept entries acknowledge intended changes, one finding\neach; an entry\nthat matches no finding fails the run, unless \\-\\-fail\\-on is never.\n.SH ARGUMENTS\n.TP\n\\fI<old>\\fR\nthe earlier contract: a file, git:<ref>[:<path>] or\nmod://<module>@<version>/<path>\n.TP\n\\fI[new]\\fR\nthe later contract (default the one built from the current spec and conf)\n.SH \"OPTIONS\"\n.TP\n\\fB\\-\\-spec\\fR \\fIstring\\fR\npath to the spec file (default the .rotini.spec.* in the working directory)\n.TP\n\\fB\\-c\\fR, \\fB\\-\\-config\\fR \\fIstring\\fR\npath to the rotini conf file (default the .rotini.conf.* beside the spec)\n.TP\n\\fB\\-\\-release\\fR \\fIX.Y.Z\\fR\nreport a removal the old contract planned for this release or earlier as\nexpected; defaults to the variable validate.release_env names\n.TP\n\\fB\\-\\-fail\\-on\\fR \\fIstring\\fR\nthe least severe change that fails the run (default breaking)\n[breaking|possibly|never]\n.TP\n\\fB\\-\\-format\\fR \\fIstring\\fR\nhow to write the findings (default text) [text|json]\n.SH \"GLOBAL OPTIONS\"\n.TP\n\\fB\\-\\-version\\fR\nprint version\n.TP\n\\fB\\-h\\fR, \\fB\\-\\-help\\fR\nprint help\n.SH OUTPUT\nEvery change between the contracts, the acknowledgements that matched none, and\nthe counts.\n.PP\nWrites \\fBobject\\fR to standard output.\n.TP\n\\fBfindings\\fR \\fI[]object\\fR\nThe changes, most severe first, then by where. (required)\n.TP\n\\fBsummary\\fR \\fIobject\\fR\nThe changes by severity; an accepted change counts only as accepted. (required)\n.TP\n\\fBunmatched_accepts\\fR \\fI[]object\\fR\nThe diff.accept entries that matched no change. (required)\n.SH \"EXIT STATUS\"\n.TP\n\\fB0\\fR (ok)\nno change at or above \\-\\-fail\\-on\n.TP\n\\fB1\\fR (error)\na contract, the spec or the conf could not be read\n.TP\n\\fB2\\fR (breaking)\na change at or above \\-\\-fail\\-on, or a diff.accept entry that matched no\nfinding (unless \\-\\-fail\\-on is never)\n.SH NOTES\nUse \"rotini help <command>\" for more information about a command.\n.SH EXAMPLES\n.RS 4\n.nf\nrotini diff git:v1.2.0\n.sp\nrotini diff git:v1.2.0 \\-\\-release 2.0.0\n.sp\nrotini diff old/cli\\-contract.json cli\\-contract.json \\-\\-format json\n.fi\n.RE\n.SH \"SEE ALSO\"\n\\fBrotini\\fR(1)\n"

// ManSection is the man section these pages were generated for: the number after the dot in a
// page's file name (<page-name>.1) and in the cross-references between pages.
const ManSection = "1"

// Man returns the generated man page text for the command identified by path
// (command names or aliases; no arguments for the root command). It returns an
// error when path does not match a known command.
func Man(path ...string) (string, error) {
	switch rotiniCanonicalPath(path) {
	case "":
		return ManRotini, nil
	case "initialize":
		return ManRotiniInitialize, nil
	case "import":
		return ManRotiniImport, nil
	case "import cobra":
		return ManRotiniImportCobra, nil
	case "import kong":
		return ManRotiniImportKong, nil
	case "import urfave":
		return ManRotiniImportUrfave, nil
	case "generate":
		return ManRotiniGenerate, nil
	case "validate":
		return ManRotiniValidate, nil
	case "tree":
		return ManRotiniTree, nil
	case "explain":
		return ManRotiniExplain, nil
	case "fmt":
		return ManRotiniFmt, nil
	case "mount":
		return ManRotiniMount, nil
	case "help":
		return ManRotiniHelp, nil
	case "version":
		return ManRotiniVersion, nil
	case "completion":
		return ManRotiniCompletion, nil
	case "man":
		return ManRotiniMan, nil
	case "diff":
		return ManRotiniDiff, nil
	default:
		return "", fmt.Errorf("no man page for command %q", strings.Join(path, " "))
	}
}

// ManPages returns every command's man page, root first in tree order, leaving out
// hidden commands and the commands below them, then each help topic's page (with Topic set).
// Each page's Content is what Man returns for its Path.
func ManPages() []rotini.Page {
	return []rotini.Page{
		{Name: "rotini", Path: nil, Content: ManRotini},
		{Name: "rotini-initialize", Path: []string{"initialize"}, Content: ManRotiniInitialize},
		{Name: "rotini-import", Path: []string{"import"}, Content: ManRotiniImport},
		{Name: "rotini-import-cobra", Path: []string{"import", "cobra"}, Content: ManRotiniImportCobra},
		{Name: "rotini-import-kong", Path: []string{"import", "kong"}, Content: ManRotiniImportKong},
		{Name: "rotini-import-urfave", Path: []string{"import", "urfave"}, Content: ManRotiniImportUrfave},
		{Name: "rotini-generate", Path: []string{"generate"}, Content: ManRotiniGenerate},
		{Name: "rotini-validate", Path: []string{"validate"}, Content: ManRotiniValidate},
		{Name: "rotini-tree", Path: []string{"tree"}, Content: ManRotiniTree},
		{Name: "rotini-explain", Path: []string{"explain"}, Content: ManRotiniExplain},
		{Name: "rotini-fmt", Path: []string{"fmt"}, Content: ManRotiniFmt},
		{Name: "rotini-mount", Path: []string{"mount"}, Content: ManRotiniMount},
		{Name: "rotini-help", Path: []string{"help"}, Content: ManRotiniHelp},
		{Name: "rotini-version", Path: []string{"version"}, Content: ManRotiniVersion},
		{Name: "rotini-completion", Path: []string{"completion"}, Content: ManRotiniCompletion},
		{Name: "rotini-man", Path: []string{"man"}, Content: ManRotiniMan},
		{Name: "rotini-diff", Path: []string{"diff"}, Content: ManRotiniDiff},
	}
}

var CompletionBash = "# bash completion for rotini\n# Set ROTINI_COMPLETION_MESSAGES=off to hide completion messages.\n# Completion messages show on the second TAB in bash 4.4 or later, and descriptions on the\n# second TAB in bash 4.0 or later; bash 3.2 shows descriptions, and lists candidates unquoted,\n# only when TAB has nothing to insert (see _rotini_listing).\n# Counters are set with $(( )) rather than run as (( )) commands: in bash 4.1 or later a (( ))\n# that comes to 0 fails, which ends a shell running with set -e.\n\n# compopt is missing in bash 3.2 (macOS's /bin/bash) and fails outside a completion; bash\n# before 4.4 rejects -o nosort.\n_rotini_compopt() {\n    if type compopt >/dev/null 2>&1; then\n        compopt \"$@\" 2>/dev/null || true\n    fi\n    return 0\n}\n\n# Prints messages on the second TAB (COMP_TYPE 63), then \"--\" before the candidates bash\n# lists, or the prompt again when there are none. $1 is the directive; only a file directive,\n# or none at all, falls back to files.\n_rotini_show_messages() {\n    (( ${#__rotini_messages[@]} )) || return 0\n    [[ $COMP_TYPE == 63 ]] || return 0\n    _rotini_messages_supported || return 0\n    if (( ! ${#COMPREPLY[@]} )) && [[ -z $1 || $1 == file* ]]; then\n        _rotini_compopt -o filenames\n        _rotini_paths file\n    fi\n    _rotini_print_messages\n    if (( ${#COMPREPLY[@]} )); then\n        printf -- '--'\n    else\n        printf '%s' \"${PS1@P}${COMP_LINE}\"\n    fi\n    return 0\n}\n\n# Appends each line of standard input to COMPREPLY as one candidate, unexpanded. Lines are read\n# as bytes: bash 5.2 in a UTF-8 locale reads a newline after a byte that starts a character\n# but doesn't finish one as part of the line, joining two lines.\n_rotini_add_lines() {\n    local LC_ALL=C line k=${#COMPREPLY[@]}\n    while IFS= read -r line; do\n        COMPREPLY[k++]=$line\n    done\n    return 0\n}\n\n# Appends the paths directive $1 (directory, file or file <exts>) offers to COMPREPLY, each\n# directory with a / after it. The paths come from the whole word, not only the text after a\n# word break, and are given as readline replaces them, after lead. A --flag=value word completes\n# the value, and an @path word the path after the @; that start of the word is kept.\n_rotini_paths() {\n    local LC_ALL=C IFS=$'\\n' word=$lead$cur pre=\"\" path p t ext k=${#COMPREPLY[@]}\n    [[ $word == -*=* ]] && pre=${word%%=*}=\n    path=${word#\"$pre\"}\n    if [[ $path == @* ]]; then\n        pre+=@\n        path=${path#@}\n    fi\n    while IFS= read -r p; do\n        t=$p\n        [[ $t == \"~/\"* ]] && t=$HOME/${t#\"~/\"}\n        [[ $p != */ && -d $t ]] && p+=/\n        p=$pre$p\n        COMPREPLY[k++]=${p#\"$lead\"}\n    done < <(\n        case $1 in\n            (directory) compgen -d -- \"$path\" ;;\n            (file) compgen -f -- \"$path\" ;;\n            (*)\n                compgen -d -- \"$path\"\n                ext=${1#file }\n                for ext in ${ext// /$'\\n'}; do\n                    compgen -f -X \"!*.$ext\" -- \"$path\"\n                done\n                ;;\n        esac\n    )\n    return 0\n}\n\n# Sets REPLY to the text every candidate in COMPREPLY starts with. Candidates are read by value:\n# bash 3.2 finds an array element by walking the array.\n_rotini_shared() {\n    local v\n    REPLY=${COMPREPLY[0]}\n    for v in \"${COMPREPLY[@]}\"; do\n        while [[ $v != \"$REPLY\"* ]]; do\n            REPLY=${REPLY%?}\n        done\n    done\n    # The pattern matches bytes, while ${#REPLY} and ${v:0:n} count characters: a byte that isn't\n    # valid UTF-8 can leave REPLY ending inside another candidate's character.\n    for v in \"${COMPREPLY[@]}\"; do\n        while [[ ${v:0:${#REPLY}} != \"$REPLY\" ]]; do\n            REPLY=${REPLY%?}\n        done\n    done\n    return 0\n}\n\n# ${PS1@P} needs bash 4.4 or later.\n_rotini_messages_supported() {\n    (( BASH_VERSINFO[0] > 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] >= 4) ))\n}\n\n_rotini_print_messages() {\n    printf '\\n'\n    printf '%s\\n' \"${__rotini_messages[@]}\"\n}\n\n# For the listing, sets several candidates as \"value  (description)\", padded to the longest\n# value and cut to the terminal's width. The first TAB inserts the bare value. Nothing is\n# formatted once file names were added.\n_rotini_describe() {\n    (( __rotini_described && ${#COMPREPLY[@]} > 1 && ${#COMPREPLY[@]} == ${#__rotini_descs[@]} )) || return 0\n    local v width=0 cols=${COLUMNS:-80} line k=0\n    local -a out=()\n    for v in \"${COMPREPLY[@]}\"; do\n        (( ${#v} > width )) && width=${#v}\n    done\n    # The descriptions are walked as positional parameters, in step with the candidates.\n    set -- \"${__rotini_descs[@]}\"\n    for v in \"${COMPREPLY[@]}\"; do\n        line=$v\n        if [[ -n $1 ]]; then\n            printf -v line '%-*s  (%s)' \"$width\" \"$v\" \"$1\"\n            if (( ${#line} > cols - 1 )); then\n                line=\"${line:0:cols-5}...)\"\n            fi\n        fi\n        out[k++]=$line\n        shift\n    done\n    COMPREPLY=(\"${out[@]}\")\n    return 0\n}\n\n# Sets args to the words after the program up to the cursor's word, as the program will receive\n# them. A word the completion word breaks split (--flag=value, host:port, user@host) is joined\n# again, and each word's quotes and backslashes are removed. For the cursor's word it also sets\n# lead, open and cur (see _rotini_unquote). COMP_LINE places the words; without it, COMP_WORDS is\n# taken as is.\n_rotini_words() {\n    local i word space pos=0 last\n    local -a raw=()\n    for (( i = 0; i <= COMP_CWORD; i++ )); do\n        word=${COMP_WORDS[i]}\n        space=${COMP_LINE:pos}\n        space=${space%%[![:space:]]*}\n        pos=$(( pos + ${#space} ))\n        if [[ ${COMP_LINE:pos:${#word}} != \"$word\" ]]; then\n            raw=(\"${COMP_WORDS[@]:0:COMP_CWORD+1}\")\n            break\n        fi\n        pos=$(( pos + ${#word} ))\n        last=$(( ${#raw[@]} - 1 ))\n        if (( i > 1 )) && [[ -z $space && -n $joins ]] && [[ $word == [\"$joins\"]* || ${raw[last]} == *[\"$joins\"] ]]; then\n            raw[last]+=$word\n        else\n            raw+=(\"$word\")\n        fi\n    done\n    for (( i = 1; i < ${#raw[@]}; i++ )); do\n        _rotini_unquote \"${raw[i]}\"\n        args+=(\"$REPLY\")\n    done\n    cur=${REPLY:${#lead}}\n    return 0\n}\n\n# Sets REPLY to $1 with its quotes and backslashes removed, expanding nothing. Readline replaces\n# only the end of the word: the text after a quote the word leaves open (open is set to that\n# quote), or else after the last unquoted word break. lead is set to the unquoted text before\n# that part, and cur to the part itself. plain is set when $1 holds no quote or backslash.\n_rotini_unquote() {\n    local w=$1 c q=\"\" i=0 brk=\"\" qlead=\"\"\n    REPLY=\"\"\n    plain=1\n    [[ $w == *[\\'\\\"\\\\]* ]] && plain=\"\"\n    while (( i < ${#w} )); do\n        c=${w:i:1}\n        if [[ $q == \"'\" ]]; then\n            if [[ $c == \"'\" ]]; then q=\"\"; else REPLY+=$c; fi\n        elif [[ $q == '\"' ]]; then\n            if [[ $c == '\"' ]]; then\n                q=\"\"\n            elif [[ $c == '\\' && ${w:i+1:1} == [\\\"\\\\\\$\\`] ]]; then\n                i=$(( i + 1 ))\n                REPLY+=${w:i:1}\n            else\n                REPLY+=$c\n            fi\n        else\n            case $c in\n                [\\'\\\"])\n                    q=$c\n                    qlead=$REPLY\n                    ;;\n                \\\\)\n                    i=$(( i + 1 ))\n                    REPLY+=${w:i:1}\n                    ;;\n                *)\n                    REPLY+=$c\n                    [[ -n $joins && $joins == *\"$c\"* ]] && brk=$REPLY\n                    ;;\n            esac\n        fi\n        i=$(( i + 1 ))\n    done\n    open=$q\n    lead=$brk\n    [[ -n $q ]] && lead=$qlead\n    return 0\n}\n\n# Sets REPLY to $1 quoted for readline to insert: inside the quote the word leaves open, or else\n# with backslashes. Pieces quoted this way can be joined.\n_rotini_quote() {\n    REPLY=\"\"\n    [[ -n $1 ]] || return 0\n    case $open in\n        \"'\")\n            REPLY=${1//\\'/\\'\\\\\\'\\'}\n            ;;\n        '\"')\n            REPLY=${1//\\\\/\\\\\\\\}\n            REPLY=${REPLY//\\\"/\\\\\\\"}\n            REPLY=${REPLY//\\$/\\\\\\$}\n            REPLY=${REPLY//\\`/\\\\\\`}\n            # History expansion reads ! even inside double quotes.\n            REPLY=${REPLY//!/\\\"\\'!\\'\\\"}\n            ;;\n        *)\n            # printf %q also escapes , and ^, which a word only needs quoted inside an unquoted\n            # {...} (its braces are escaped too) or at the start of a line.\n            printf -v REPLY '%q' \"$1\"\n            [[ $REPLY == \"\\$'\"* ]] || { REPLY=${REPLY//\\\\,/,}; REPLY=${REPLY//\\\\^/^}; }\n            ;;\n    esac\n    return 0\n}\n\n# Quotes each candidate in COMPREPLY as one literal word for readline to insert. Readline\n# inserts the text several candidates share, so the first candidate quotes the character where\n# they part in another way, and the shared text never ends inside one character's quoting.\n# Candidates are read by value: bash 3.2 finds an array element by walking the array.\n_rotini_quote_all() {\n    local v c p rest pre=\"\" qpre head n=${#COMPREPLY[@]} first=1 k=0\n    local -a out=()\n    if (( n > 1 )); then\n        _rotini_shared\n        pre=$REPLY\n    fi\n    p=${#pre}\n    _rotini_quote \"$pre\"\n    qpre=$REPLY\n    for v in \"${COMPREPLY[@]}\"; do\n        c=${v:p:1}\n        head=\"\"\n        if (( first && n > 1 )) && [[ -z $open && -n $c ]]; then\n            printf -v head '%q' \"$c\"\n            if [[ $head == \"$c\" || $c == [,^] ]]; then\n                head=\"\"\n            elif [[ $c == \"'\" ]]; then\n                head=\"\\\"'\\\"\"\n            else\n                head=\"'$c'\"\n            fi\n        fi\n        first=0\n        if [[ -n $head ]]; then\n            rest=${v:p+1}\n        else\n            rest=${v:p}\n        fi\n        # The common case of _rotini_quote, without the cost of a call per candidate.\n        if [[ -z $rest ]]; then\n            REPLY=\"\"\n        elif [[ -z $open ]]; then\n            printf -v REPLY '%q' \"$rest\"\n            [[ $REPLY == \"\\$'\"* ]] || { REPLY=${REPLY//\\\\,/,}; REPLY=${REPLY//\\\\^/^}; }\n        else\n            _rotini_quote \"$rest\"\n        fi\n        REPLY=$qpre$head$REPLY\n        # Readline closes the quote left open, unless the text already ends with that quote.\n        case $open in\n            \"\")\n                # bash before 5 leaves a leading ~ bare, which would expand to a home directory.\n                [[ $REPLY == \"~\"* ]] && REPLY=\"\\\\$REPLY\"\n                ;;\n            \"'\")\n                [[ $v == *\"'\" ]] && REPLY=${REPLY%\"'\\\\''\"}\"'\\\\'\"\n                ;;\n            '\"')\n                [[ $v == *'\"' ]] && REPLY=${REPLY%'\\\"'}'\"\\\"'\n                [[ $v == *'!' ]] && REPLY+='\"'\n                ;;\n        esac\n        out[k++]=$REPLY\n    done\n    COMPREPLY=(\"${out[@]}\")\n    return 0\n}\n\n# Reads the program's output from standard input into COMPREPLY, __rotini_descs, __rotini_messages,\n# options and directive. Output: candidates as \"name<TAB>description\", then\n# \":rotini:message <text>\" lines, then a \":rotini:option <word>...\" line (nospace, keep-order),\n# then a \":rotini:<directive>\" line (none, file, file <exts>, directory, executable, user, group,\n# host). Read line by line, as bytes (see _rotini_add_lines): an unquoted $(...) would also\n# glob-expand each candidate.\n_rotini_read_output() {\n    local LC_ALL=C line value i=0\n    while IFS= read -r line; do\n        case \"$line\" in\n            \":rotini:message \"*) __rotini_messages+=(\"${line#:rotini:message }\") ;;\n            \":rotini:option \"*) options=\" ${line#:rotini:option } \" ;;\n            \":rotini:\"*) directive=\"${line#:rotini:}\" ;;\n            *)\n                # Readline replaces only the text after lead.\n                value=${line%%$'\\t'*}\n                [[ $value == \"$lead\"* ]] && value=${value#\"$lead\"}\n                COMPREPLY[i]=$value\n                __rotini_descs[i]=\"\"\n                if [[ $line == *$'\\t'* ]]; then\n                    __rotini_descs[i]=${line#*$'\\t'}\n                    __rotini_described=1\n                fi\n                i=$(( i + 1 ))\n                ;;\n        esac\n    done\n    return 0\n}\n\n_rotini_complete() {\n    local cur=\"\" lead=\"\" open=\"\" plain=\"\" directive=\"\" options=\"\" REPLY joins prog=rotini\n    local -a args=() kept=()\n    __rotini_messages=()\n    __rotini_descs=()\n    __rotini_described=0\n    # The word breaks that can sit inside one word; the rest end the word or quote.\n    joins=${COMP_WORDBREAKS//[[:space:]\\\"\\'\\;\\|\\&\\(\\)\\<\\>]/}\n    # The program typed as a path is run from that path, with a leading ~ expanded; a bare name\n    # runs the rotini found on PATH. ~name is not expanded.\n    _rotini_unquote \"${COMP_WORDS[0]}\"\n    if [[ $REPLY == */* ]]; then\n        prog=$REPLY\n        [[ ${COMP_WORDS[0]} == \"~/\"* ]] && prog=$HOME/${REPLY#\"~/\"}\n    fi\n    # Before narrowing IFS: bash 3.2 joins an array slice into one word otherwise.\n    _rotini_words\n    COMPREPLY=()\n    local IFS=$'\\n'\n    _rotini_read_output < <(\"$prog\" __complete \"${args[@]}\" 2>/dev/null)\n\n    [[ $options == *\" nospace \"* ]] && _rotini_compopt -o nospace\n    [[ $options == *\" keep-order \"* ]] && _rotini_compopt -o nosort\n    case \"$directive\" in\n        none)\n            _rotini_compopt +o default\n            ;;\n        directory | file*)\n            _rotini_compopt -o filenames\n            _rotini_paths \"$directive\"\n            # Readline adds a space after a lone directory unless told not to. bash 3.2 can't be\n            # told: there what is in the directory is offered instead, which readline completes\n            # up to the / and lists. A directory holding one match still gets the space.\n            if (( ${#COMPREPLY[@]} == 1 )) && [[ ${COMPREPLY[0]} == */ ]]; then\n                if type compopt >/dev/null 2>&1; then\n                    _rotini_compopt -o nospace\n                else\n                    kept=(\"$cur\" \"${COMPREPLY[0]}\")\n                    cur=${COMPREPLY[0]}\n                    COMPREPLY=()\n                    _rotini_paths \"$directive\"\n                    cur=${kept[0]}\n                    (( ${#COMPREPLY[@]} )) || COMPREPLY=(\"${kept[1]}\")\n                fi\n            fi\n            ;;\n        executable)\n            _rotini_compopt +o default\n            _rotini_add_lines < <(compgen -c -- \"$cur\")\n            ;;\n        user)\n            _rotini_compopt +o default\n            _rotini_add_lines < <(compgen -u -- \"$cur\")\n            ;;\n        group)\n            _rotini_compopt +o default\n            _rotini_add_lines < <(compgen -g -- \"$cur\")\n            ;;\n        host)\n            _rotini_compopt +o default\n            _rotini_add_lines < <(compgen -A hostname -- \"$cur\")\n            ;;\n    esac\n    # Readline inserts a candidate, or what several share, as given: quote each one so spaces\n    # and shell characters stay part of the word. The listing (COMP_TYPE 63) shows them as\n    # they are. -o filenames quotes file names, and every candidate with them, where bash has\n    # compopt to set it.\n    if [[ -z $COMP_TYPE ]] && _rotini_listing; then\n        return 0\n    fi\n    if (( ${#COMPREPLY[@]} )) && [[ $COMP_TYPE != 63 ]]; then\n        if [[ $directive != file* && $directive != directory ]] || ! type compopt >/dev/null 2>&1; then\n            _rotini_quote_all\n        fi\n    fi\n    [[ $COMP_TYPE == 63 ]] && _rotini_describe\n    _rotini_show_messages \"$directive\"\n}\n\n# bash 3.2 has no COMP_TYPE to tell the TAB that inserts from the one that lists. When the word\n# was typed without quotes and the candidates share nothing past it, both TABs leave the word as\n# it is, so the candidates stay unquoted for the listing, with their descriptions when those\n# still share nothing more. Fails, leaving COMPREPLY as it was, otherwise.\n_rotini_listing() {\n    local -a bare\n    (( ${#COMPREPLY[@]} > 1 )) && [[ -n $plain && -z $open ]] || return 1\n    _rotini_shared\n    [[ $REPLY == \"$cur\" ]] || return 1\n    bare=(\"${COMPREPLY[@]}\")\n    _rotini_describe\n    _rotini_shared\n    [[ $REPLY == \"$cur\" ]] || COMPREPLY=(\"${bare[@]}\")\n    return 0\n}\ncomplete -o default -F _rotini_complete rotini\n"

var CompletionZsh = "#compdef rotini\n# zsh completion for rotini\n# Set ROTINI_COMPLETION_MESSAGES=off to hide completion messages.\n_rotini() {\n    local -a args lines pairs names shown exts msgs opts expl\n    local line name desc directive=\"\" options=\"\" msg prog=rotini dir\n    integer width i\n    # (Q) removes the quotes and backslashes the words were typed with. Inside a quote the\n    # current word is the text after it, so it is quoted again first. The empty current word is\n    # passed too, so \"rotini --flag \" completes the flag's values.\n    args=(\"${(@Q)words[2,CURRENT-1]}\")\n    if [[ -n $compstate[quote] ]]; then\n        args+=(\"${(Q)${:-$compstate[quote]$PREFIX$SUFFIX$compstate[quote]}}\")\n    else\n        args+=(\"${(Q)words[CURRENT]}\")\n    fi\n    # The program typed as a path is run from that path, with a leading ~ or ~name expanded as\n    # zsh would; a bare name runs the rotini found on PATH.\n    if [[ ${(Q)words[1]} == */* ]]; then\n        prog=${(Q)words[1]}\n        if [[ $words[1] == '~'* ]]; then\n            name=${${prog%%/*}#\\~}\n            if [[ -z $name ]]; then\n                dir=$HOME\n            else\n                dir=${nameddirs[$name]:-$userdirs[$name]}\n            fi\n            [[ -n $dir ]] && prog=$dir/${prog#*/}\n        fi\n    fi\n    lines=(${(f)\"$(\"$prog\" __complete \"${args[@]}\" 2>/dev/null)\"})\n    # Output: candidates as \"name<TAB>description\", then \":rotini:message <text>\" lines, then\n    # a \":rotini:option <word>...\" line (nospace, keep-order, ignore-case), then a\n    # \":rotini:<directive>\" line (none, file, file <exts>, directory, executable, user, group,\n    # host).\n    for line in $lines; do\n        if [[ $line == ':rotini:message '* ]]; then\n            msgs+=(\"${line#:rotini:message }\")\n            continue\n        fi\n        if [[ $line == ':rotini:option '* ]]; then\n            options=\" ${line#:rotini:option } \"\n            continue\n        fi\n        if [[ $line == ':rotini:'* ]]; then\n            directive=${line#:rotini:}\n            continue\n        fi\n        name=${line%%$'\\t'*} desc=\n        [[ $line == *$'\\t'* ]] && desc=${line#*$'\\t'}\n        names+=(\"$name\")\n        shown+=(\"$desc\")\n        (( $#desc && $#name > width )) && width=$#name\n        # _describe reads a backslash as an escape, and a colon in a name as the end of it.\n        if [[ $line == *$'\\t'* ]]; then\n            pairs+=(\"${${name//\\\\/\\\\\\\\}//:/\\\\:}:${${desc//\\\\/\\\\\\\\}//:/\\\\:}\")\n        else\n            pairs+=(\"${${line//\\\\/\\\\\\\\}//:/\\\\:}\")\n        fi\n    done\n    for msg in $msgs; do\n        _message -r \"$msg\"\n    done\n    [[ $options == *\" nospace \"* ]] && opts+=(-S '')\n    # The candidates match the typed word in any case: so must zsh, which otherwise keeps only\n    # those that match it exactly.\n    [[ $options == *\" ignore-case \"* ]] && opts+=(-M 'm:{[:lower:][:upper:]}={[:upper:][:lower:]}')\n    if (( $#pairs )); then\n        if [[ $options == *\" keep-order \"* ]]; then\n            # _describe lists the candidates without a description after the others, so these\n            # are added as one unsorted group, each shown as _describe shows it.\n            if (( width )); then\n                for (( i = 1; i <= $#names; i++ )); do\n                    [[ -n $shown[i] ]] && shown[i]=\"${(r:width:)names[i]}  -- $shown[i]\" || shown[i]=$names[i]\n                done\n                opts+=(-l -d shown)\n            fi\n            _wanted -V values expl 'rotini' compadd \"${opts[@]}\" -a names\n        else\n            _describe 'rotini' pairs \"${opts[@]}\"\n        fi\n    fi\n\n    # A --flag=value word completes the value, and for a path an @path word the path after the\n    # @; what comes before stays in the word.\n    if [[ $directive == (directory|file*|user|group|) ]]; then\n        [[ $PREFIX == -*=* ]] && compset -P 1 '*='\n        [[ $directive == (directory|file*) ]] && compset -P '@'\n    fi\n    case $directive in\n        none) return 0 ;;\n        # _files -/ offers every file when there is no directory.\n        directory) _wanted directories expl directory _path_files -/ ;;\n        file) _files ;;\n        # _files reads *.(ext) as a glob qualifier.\n        \"file \"*)\n            exts=(${=directive#file })\n            if (( $#exts == 1 )); then\n                _files -g \"*.$exts[1]\"\n            else\n                _files -g \"*.(${(j:|:)exts})\"\n            fi\n            ;;\n        executable) _command_names -e ;;\n        user) _users ;;\n        group) _groups ;;\n        host) _hosts ;;\n        # No directive: files, as the other shells fall back to.\n        \"\") (( $#pairs )) || _files ;;\n    esac\n}\n\n# Loaded from $fpath, the file runs as the function on the first TAB: complete that one too.\n# Sourced, it registers the function, which needs compinit.\nif [[ $zsh_eval_context[-1] == loadautofunc ]]; then\n    _rotini \"$@\"\nelif (( $+functions[compdef] )); then\n    compdef _rotini rotini\nelse\n    print -ru2 -- \"rotini completion needs compinit: run autoload -Uz compinit && compinit first\"\n    false\nfi\n"

var CompletionFish = "# fish completion for rotini\n# Set ROTINI_COMPLETION_MESSAGES=off to hide completion messages.\n# Output: candidates as \"name<TAB>description\", then \":rotini:message <text>\" lines (fish\n# doesn't show them), then a \":rotini:option <word>...\" line, then a \":rotini:<directive>\" line\n# (none, file, file <exts>, directory, executable, user, group, host). The candidates come in\n# the order to show them, so they are registered with --keep-order (fish 3.1 or later). fish\n# adds no space after a candidate ending in = on its own.\n\n# Prints the candidates, or when there are none, what fish completes for the directive. One\n# call per TAB, so the program runs once.\nfunction __rotini_complete\n    # The words without the quotes and backslashes they were typed with; the current word is\n    # quoted so that, even empty, it is passed.\n    set -l cur (string unescape -- (commandline -ct))\n    set -l tokens (commandline -opc)\n    set -a tokens \"$cur\"\n    # The program typed as a path is run from that path, with a leading ~ expanded; a bare name\n    # runs the rotini found on PATH. ~name is not expanded.\n    set -l prog rotini\n    if string match -q -- '~/*' $tokens[1]\n        set prog $HOME/(string sub -s 3 -- $tokens[1])\n    else if string match -q -- '*/*' $tokens[1]\n        set prog $tokens[1]\n    end\n    set -l results\n    set -l directive \"\"\n    for line in ($prog __complete $tokens[2..-1] 2>/dev/null)\n        if string match -q ':rotini:message *' -- $line\n            continue\n        else if string match -q ':rotini:option *' -- $line\n            continue\n        else if string match -q ':rotini:*' -- $line\n            set directive (string replace ':rotini:' '' -- $line)\n        else\n            set -a results $line\n        end\n    end\n    if set -q results[1]\n        printf '%s\\n' $results\n    else if test \"$directive\" != none\n        __rotini_files \"$directive\" \"$cur\"\n    end\nend\n\n# The shell's own completions for directive $1, with $2 the current word: paths, and the names\n# fish's own helpers list (checked with fish 4.6).\n# A --flag=value word completes the value, and for a path an @path word the path after the @;\n# that start of the word is completed without, and put back on each name.\nfunction __rotini_files\n    set -l lead (string match -r -- '^-[^=]*=' $argv[2])\n    if string match -q -r -- '^(directory|file)' $argv[1]; and string match -q -- \"$lead@*\" $argv[2]\n        set lead \"$lead@\"\n    end\n    set -l n (math (string length -- \"$lead\") + 1)\n    set -l word (string sub -s $n -- \"$argv[2]\")\n    set -l raw (commandline -ct)\n    set raw (string sub -s $n -- \"$raw\")\n    for line in (__rotini_names $argv[1] \"$word\" \"$raw\")\n        printf '%s%s\\n' \"$lead\" $line\n    end\nend\n\n# Prints the names for directive $1, with $2 the word to complete and $3 that word as typed,\n# still escaped, which is what fish's path helpers read.\nfunction __rotini_names\n    switch $argv[1]\n        case directory\n            __fish_complete_directories $argv[3]\n        case 'file *'\n            __fish_complete_directories $argv[3]\n            for ext in (string split ' ' -- (string replace 'file ' '' -- $argv[1]))\n                for f in $argv[2]*.$ext\n                    test -f $f; and echo $f\n                end\n            end\n        case executable\n            __fish_complete_command\n        case user\n            __fish_complete_users\n        case group\n            __fish_complete_groups\n        case host\n            __fish_print_hostnames\n        case '*'\n            __fish_complete_path $argv[3]\n    end\nend\n\ncomplete -c rotini -f\ncomplete -c rotini -f -k -a '(__rotini_complete)'\n"

var CompletionPowershell = "# PowerShell completion for rotini\n# Set ROTINI_COMPLETION_MESSAGES=off to hide completion messages.\nRegister-ArgumentCompleter -Native -CommandName rotini -ScriptBlock {\n    param($wordToComplete, $commandAst, $cursorPosition)\n    # Each word up to the cursor as the program receives it, without the quotes it was typed\n    # with. The word at the cursor is cut there; one cut inside its quotes only loses the\n    # opening quote.\n    $typed = ''\n    $tokens = @($commandAst.CommandElements | Select-Object -Skip 1 |\n        Where-Object { $_.Extent.StartOffset -lt $cursorPosition } | ForEach-Object {\n        if ($_.Extent.EndOffset -gt $cursorPosition) {\n            $typed = $_.Extent.Text.Substring(0, $cursorPosition - $_.Extent.StartOffset)\n            $typed -replace '^[''\"\\u2018-\\u201E]', ''\n        }\n        elseif ($_ -is [System.Management.Automation.Language.StringConstantExpressionAst] -or\n            $_ -is [System.Management.Automation.Language.ExpandableStringExpressionAst]) { $_.Value }\n        elseif ($_.Extent.Text -ceq \"@('--%')\") { '--%' }\n        else { $_.Extent.Text }\n    })\n    $partial = ''\n    if ($wordToComplete -ne '' -and $tokens.Count) {\n        $partial = $tokens[-1]\n        if (-not $typed) { $typed = $wordToComplete }\n    }\n    # Pass the empty current word; before PowerShell 7.3, and with Legacy argument passing, an\n    # empty argument only survives as '\"\"'.\n    if ($wordToComplete -eq '') {\n        $legacy = $PSVersionTable.PSVersion -lt [version]'7.3' -or $PSNativeCommandArgumentPassing -eq 'Legacy'\n        $tokens += $(if ($legacy) { '\"\"' } else { '' })\n    }\n    # The program typed as a path is run from that path, with a leading ~ expanded; a bare name\n    # runs the rotini found on PATH.\n    $prog = 'rotini'\n    $first = $commandAst.CommandElements[0]\n    if ($first -is [System.Management.Automation.Language.StringConstantExpressionAst] -and $first.Value -match '[\\\\/]') {\n        $prog = $first.Value -replace '^~(?=[\\\\/])', $HOME.Replace('$', '$$')\n    }\n    # Passed as an array, not splatted: splatting drops a --% word.\n    $lines = @(& $prog __complete $tokens 2>$null)\n    # Output: candidates as \"name<TAB>description\", then \":rotini:message <text>\" lines (not\n    # shown in PowerShell), then a \":rotini:option <word>...\" line, then a \":rotini:<directive>\"\n    # line (none, file, file <exts>, directory, executable, user, group, host). PowerShell shows\n    # the candidates in the order given and adds no space after one.\n    $lines = @($lines | Where-Object { $_ -notlike ':rotini:message *' -and $_ -notlike ':rotini:option *' })\n    $directive = ($lines | Where-Object { $_ -like ':rotini:*' } | Select-Object -Last 1)\n    $candidates = $lines | Where-Object { $_ -notlike ':rotini:*' }\n\n    $candidates | ForEach-Object {\n        $parts = $_ -split \"`t\", 2\n        $text = $parts[0]\n        $tip = if ($parts.Count -gt 1 -and $parts[1]) { $parts[1] } else { $text }\n        # PowerShell inserts the text as typed, so quote one with spaces, wildcards, shell\n        # characters or a leading ~ (a home directory to native commands). PowerShell splits a\n        # bare argument that starts with a dash (- or U+2013 to U+2015) at a ., and reads one\n        # ending in : as a parameter awaiting its value, so quote a dashed value holding either.\n        # It drops the argument --% however it is quoted, and passes it only from an array. It\n        # reads the typographic quotes U+2018 to U+201E as quotes too, and inside single quotes\n        # doubles each form of single quote.\n        $insert = if ($text -ceq '--%') { \"@('--%')\" }\n            elseif ($text -match '^~|^[-\\u2013-\\u2015].*[.:]|[\\s''\"$&|;<>(){}@#,*?\\[\\]`\\u2018-\\u201E]') { \"'\" + ($text -replace '[''\\u2018-\\u201B]', '$0$0') + \"'\" }\n            else { $text }\n        [System.Management.Automation.CompletionResult]::new($insert, $text, 'ParameterValue', $tip)\n    }\n\n    if ($directive) {\n        $hint = $directive -replace '^:rotini:', ''\n        # The names for executable, user and group; PowerShell has no host completer, and lists\n        # users and groups on Windows only.\n        $names = $null\n        $paths = $null\n        # A --flag=value word completes the value, and for a path an @path word the path after\n        # the @; that start of the word stays, and the whole word is then quoted.\n        $lead = ''\n        if ($hint -like 'directory' -or $hint -like 'file*') {\n            if ($partial -match '^-[^=]*=') { $lead = $Matches[0] }\n            if ($partial.Substring($lead.Length).StartsWith('@')) { $lead += '@' }\n        }\n        $pathWord = if ($lead) { $partial.Substring($lead.Length) } else { $typed }\n        switch -Wildcard ($hint) {\n            # An empty string stops PowerShell's fallback to file names.\n            'none' { if (-not $candidates) { '' }; return }\n            # PowerShell's own file name completion keeps the typed folder and quotes the names.\n            'directory' {\n                $paths = @([System.Management.Automation.CompletionCompleters]::CompleteFilename($pathWord) |\n                    Where-Object { $_.ResultType -eq 'ProviderContainer' })\n            }\n            'file *' {\n                $exts = ($hint -replace '^file ', '') -split ' '\n                $paths = @([System.Management.Automation.CompletionCompleters]::CompleteFilename($pathWord) |\n                    Where-Object { $_.ResultType -eq 'ProviderContainer' -or $exts -contains [System.IO.Path]::GetExtension($_.ToolTip).TrimStart('.') })\n            }\n            'file' {\n                $paths = @([System.Management.Automation.CompletionCompleters]::CompleteFilename($pathWord))\n            }\n            'executable' {\n                $names = @(Get-Command -CommandType Application -Name \"$partial*\" -ErrorAction SilentlyContinue |\n                    ForEach-Object { $_.Name } | Sort-Object -Unique)\n            }\n            'user' {\n                $names = @()\n                if (Get-Command Get-LocalUser -ErrorAction SilentlyContinue) {\n                    $names = @(Get-LocalUser -ErrorAction SilentlyContinue | Where-Object { $_.Name -like \"$partial*\" } | ForEach-Object { $_.Name })\n                }\n            }\n            'group' {\n                $names = @()\n                if (Get-Command Get-LocalGroup -ErrorAction SilentlyContinue) {\n                    $names = @(Get-LocalGroup -ErrorAction SilentlyContinue | Where-Object { $_.Name -like \"$partial*\" } | ForEach-Object { $_.Name })\n                }\n            }\n            'host' { $names = @() }\n        }\n        if ($null -ne $paths) {\n            if ($lead) {\n                $paths | ForEach-Object {\n                    $path = $_.CompletionText\n                    if ($path -match '^''(.*)''$') { $path = $Matches[1] -replace '''''', '''' }\n                    $insert = \"'\" + (($lead + $path) -replace '[''\\u2018-\\u201B]', '$0$0') + \"'\"\n                    [System.Management.Automation.CompletionResult]::new($insert, $_.ListItemText, $_.ResultType, $_.ToolTip)\n                }\n            } else {\n                $paths\n            }\n            # With nothing to offer, PowerShell would fall back to every file name.\n            if (-not $paths -and -not $candidates) { '' }\n        }\n        if ($null -ne $names) {\n            $names | ForEach-Object { [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_) }\n            if (-not $names -and -not $candidates) { '' }\n        }\n    }\n}\n"

var CompletionNushell = "# Nushell completion for rotini\n# Set ROTINI_COMPLETION_MESSAGES=off to hide completion messages.\n# Needs Nushell 0.116 or later. Nushell runs the files in its autoload directory at startup:\n#   mkdir ($nu.user-autoload-dirs | first)\n#   rotini completion nushell | save -f ($nu.user-autoload-dirs | first | path join rotini.nu)\n\n# Output: candidates as \"name<TAB>description\", then \":rotini:message <text>\" lines (Nushell\n# doesn't show them), then a \":rotini:option <word>...\" line (nospace, keep-order), then a\n# \":rotini:<directive>\" line (none, file, file <exts>, directory, executable, user, group,\n# host). Nushell has no completer for program, user, group or host names, so those offer\n# nothing. The completer belongs to the extern named rotini: Nushell runs it only for that bare\n# name, never for rotini typed as a path, so it runs the rotini found on PATH.\ndef \"nu-complete rotini\" [place: record] {\n    let typed = ($place.command | skip 1)\n    let partial = ($typed | last)\n    # Nushell gives each word as typed. The program gets it without the quotes it was typed in,\n    # including a quote the last word leaves open.\n    let unquote = {|w|\n        if ($w =~ \"^r#+'\") {\n            let closed = ($w | parse --regex \"^r(?<h>#+)'(?<v>.*)'(?P=h)$\")\n            if ($closed | is-not-empty) { $closed.0.v } else { $w | str replace --regex \"^r#+'\" '' }\n        } else if ($w =~ \"^['`]\") {\n            $w | str replace --regex \"^(['`])(.*?)(?:\\\\1)?$\" '$2'\n        } else if ($w | str starts-with '\"') {\n            $w | str replace --regex '^\"((?:[^\"\\\\]|\\\\.)*)\"?$' '$1' | str replace --all --regex '\\\\([\"\\\\])' '$1'\n        } else {\n            $w\n        }\n    }\n    let words = ($typed | each {|w| do $unquote $w })\n    let lines = (^rotini __complete ...$words | complete | get stdout | lines)\n    let options = ($lines | where ($it | str starts-with ':rotini:option ') | each { str substring 15.. | split row ' ' } | flatten)\n    let directive = ($lines | where ($it | str starts-with ':rotini:') and not ($it | str starts-with ':rotini:message ') and not ($it | str starts-with ':rotini:option ') | each { str substring 8.. } | append '' | first)\n    let space = not ('nospace' in $options)\n    # Nushell inserts a value as given: one that isn't a plain word goes in single quotes, or\n    # in a raw string when it holds a single quote, so it stays one literal argument. Nushell\n    # reads a bare null as no value, and a bare =, += and the like as an assignment.\n    let quote = {|v|\n        if ($v =~ '^[\\w.:/=+-]+$') and not ($v | str starts-with '~') and $v != 'null' and not ($v =~ '^(\\+\\+|[+\\-/*])?=$') {\n            $v\n        } else if not ($v | str contains \"'\") {\n            $\"'($v)'\"\n        } else {\n            mut hashes = '#'\n            while ($v | str contains $\"'($hashes)\") { $hashes = $hashes + '#' }\n            $\"r($hashes)'($v)'($hashes)\"\n        }\n    }\n    mut found = ($lines | where not ($it | str starts-with ':rotini:') | each {|line|\n        let parts = ($line | split row --number 2 \"\\t\")\n        if ($parts | length) > 1 and ($parts.1 | is-not-empty) {\n            {value: (do $quote $parts.0), description: $parts.1, append_whitespace: $space}\n        } else {\n            {value: (do $quote $parts.0), append_whitespace: $space}\n        }\n    })\n    let words = ($directive | split row ' ')\n    match $words.0 {\n        'directory' => {\n            $found = ($found | append ($partial | commandline complete --type directory | each {|p| {value: $p, append_whitespace: false} }))\n        }\n        'file' => {\n            let exts = ($words | skip 1)\n            if ($exts | is-empty) {\n                if ($found | is-empty) { return null }\n                $found = ($found | append ($partial | commandline complete --type path | each {|p| {value: $p, append_whitespace: false} }))\n            } else {\n                # Nushell quotes a path it completes; the name is read inside the quotes.\n                let bare = {|p| $p | str replace --regex \"^[\\\"'`](.*)[\\\"'`]$\" '$1' }\n                let paths = ($partial | commandline complete --type path | where {|p| (do $bare $p | str ends-with '/') or ((do $bare $p | path parse | get extension) in $exts) })\n                $found = ($found | append ($paths | each {|p| {value: $p, append_whitespace: (not (do $bare $p | str ends-with '/'))} }))\n            }\n        }\n        '' => {\n            if ($found | is-empty) { return null }\n        }\n    }\n    {completions: $found, options: {sort: (not ('keep-order' in $options))}}\n}\n\n# Bare true and false are read as booleans, which reach the program as the same words.\n@complete \"nu-complete rotini\"\nextern rotini [...args: oneof<string, bool>]\n"

// Completion returns the embedded completion script for shell, or an error when
// shell is not one rotini generated a script for.
func Completion(shell string) (string, error) {
	switch shell {
	case "bash":
		return CompletionBash, nil
	case "zsh":
		return CompletionZsh, nil
	case "fish":
		return CompletionFish, nil
	case "powershell":
		return CompletionPowershell, nil
	case "nushell":
		return CompletionNushell, nil
	default:
		return "", fmt.Errorf("no completion for shell %q", shell)
	}
}
